      backup_text =
        "# SPROUTS AND SHROOMS #\n\
         # Tic-tac-toe in the night garden: sprouts race shrooms for three in \
         a row #\n\n\
         type Cell = + Empty + Sprout + Shroom in\n\n\
         type Board = [Cell] in  # 9 cells, row-major: [0,1,2,3,4,5,6,7,8] #\n\n\
         type Player = + PlayerSprout + PlayerShroom in\n\n\
         type GameStatus =\n\
        \  + InProgress\n\
        \  + Won(Player)\n\
        \  + Draw\n\
         in\n\n\
         type Model = (\n\
        \  board = Board,\n\
        \  turn = Player,\n\
        \  status = GameStatus\n\
         ) in\n\n\
         type Msg = + ClickCell(Int) + NewGame in\n\n\
         let emptyBoard: Board =\n\
        \  [Empty, Empty, Empty,\n\
        \   Empty, Empty, Empty,\n\
        \   Empty, Empty, Empty]\n\
         in\n\n\
         let init: Model = (\n\
        \  board = emptyBoard,\n\
        \  turn = PlayerSprout,\n\
        \  status = InProgress\n\
         ) in\n\n\
         let getCell(board: Board, pos: Int): Cell = nth(board, pos) in\n\n\
         let setCell(board: Board, pos: Int, cell: Cell): Board =\n\
        \  mapi(board, fun (i, c) -> if i == pos then cell else c)\n\
         in\n\n\
         let playerCell(p: Player): Cell =\n\
        \  case p\n\
        \  | PlayerSprout => Sprout\n\
        \  | PlayerShroom => Shroom\n\
        \  end\n\
         in\n\n\
         let cellStr(c: Cell): String =\n\
        \  case c\n\
        \  | Empty => \" \"\n\
        \  | Sprout => \"\240\159\140\177\"\n\
        \  | Shroom => \"\240\159\141\132\"\n\
        \  end\n\
         in\n\n\
         # Three matching non-empty cells win a line #\n\
         let threeInRow(a: Cell, b: Cell, c: Cell): Option =\n\
        \  case (a, b, c)\n\
        \  | (Sprout, Sprout, Sprout) => Some(Sprout)\n\
        \  | (Shroom, Shroom, Shroom) => Some(Shroom)\n\
        \  | _ => None\n\
        \  end\n\
         in\n\n\
         let getCells3(board: Board, i: Int, j: Int, k: Int): (Cell, Cell, \
         Cell) =\n\
        \  (getCell(board, i), getCell(board, j), getCell(board, k))\n\
         in\n\n\
         let checkWinner(board: Board): Option =\n\
        \  # Rows #\n\
        \  let row0 = threeInRow(getCells3(board, 0, 1, 2)) in\n\
        \  let row1 = threeInRow(getCells3(board, 3, 4, 5)) in\n\
        \  let row2 = threeInRow(getCells3(board, 6, 7, 8)) in\n\
        \  # Columns #\n\
        \  let col0 = threeInRow(getCells3(board, 0, 3, 6)) in\n\
        \  let col1 = threeInRow(getCells3(board, 1, 4, 7)) in\n\
        \  let col2 = threeInRow(getCells3(board, 2, 5, 8)) in\n\
        \  # Diagonals #\n\
        \  let diag1 = threeInRow(getCells3(board, 0, 4, 8)) in\n\
        \  let diag2 = threeInRow(getCells3(board, 2, 4, 6)) in\n\
        \  # First winning line found #\n\
        \  case row0 | Some(c) => Some(c) | None =>\n\
        \  case row1 | Some(c) => Some(c) | None =>\n\
        \  case row2 | Some(c) => Some(c) | None =>\n\
        \  case col0 | Some(c) => Some(c) | None =>\n\
        \  case col1 | Some(c) => Some(c) | None =>\n\
        \  case col2 | Some(c) => Some(c) | None =>\n\
        \  case diag1 | Some(c) => Some(c) | None =>\n\
        \  diag2\n\
        \  end end end end end end end\n\
         in\n\n\
         let isFull(board: Board): Bool = for_all(board, fun c -> c != Empty) \
         in\n\n\
         let cellToPlayer(c: Cell): Player =\n\
        \  case c\n\
        \  | Sprout => PlayerSprout\n\
        \  | Shroom => PlayerShroom\n\
        \  | Empty => PlayerSprout  # shouldn't happen #\n\
        \  end\n\
         in\n\n\
         let calcStatus(board: Board): GameStatus =\n\
        \  case checkWinner(board)\n\
        \  | Some(c) => Won(cellToPlayer(c))\n\
        \  | None => if isFull(board) then Draw else InProgress\n\
        \  end\n\
         in\n\n\
         let nextPlayer(p: Player): Player =\n\
        \  case p\n\
        \  | PlayerSprout => PlayerShroom\n\
        \  | PlayerShroom => PlayerSprout\n\
        \  end\n\
         in\n\n\
         let isValidMove(m: Model, pos: Int): Bool =\n\
        \  pos >= 0 && pos < 9 &&\n\
        \  getCell(m.board, pos) == Empty &&\n\
        \  m.status == InProgress\n\
         in\n\n\
         let move(m: Model, pos: Int): Model =\n\
        \  if isValidMove(m, pos) then\n\
        \    let newBoard = setCell(m.board, pos, playerCell(m.turn)) in\n\
        \    (\n\
        \      board = newBoard,\n\
        \      turn = nextPlayer(m.turn),\n\
        \      status = calcStatus(newBoard)\n\
        \    )\n\
        \  else m  # Invalid move, no change #\n\
         in\n\n\
         let update(msg: Msg, m: Model): (Model, Cmd) =\n\
        \  case msg\n\
        \  | ClickCell(pos) => (move(m, pos), CmdNone)\n\
        \  | NewGame => (init, CmdNone)\n\
        \  end\n\
         in\n\n\
         # ===== VIEW ===== #\n\n\
         let view(model: Model): HTML =\n\
        \  let playerName(p: Player): String =\n\
        \    case p\n\
        \    | PlayerSprout => \"Sprout\"\n\
        \    | PlayerShroom => \"Shroom\"\n\
        \    end\n\
        \  in\n\
        \  let statusText =\n\
        \    case model.status\n\
        \    | InProgress => playerName(model.turn) ++ \"'s turn\"\n\
        \    | Won(p) => playerName(p) ++ \" wins!\"\n\
        \    | Draw => \"The plot is full - a draw!\"\n\
        \    end\n\
        \  in\n\
        \  let boardRow(positions: [Int]): HTML =\n\
        \    Div([Style([(\"display\", \"flex\")])],\n\
        \      map(positions, fun pos ->\n\
        \        Button(\n\
        \          [\n\
        \            OnClick(ClickCell(pos)),\n\
        \            Style([\n\
        \              (\"width\", \"80px\"), (\"height\", \"80px\"), \
         (\"font-size\", \"36px\"),\n\
        \              (\"border\", \"1px solid #30363d\"), (\"cursor\", \
         \"pointer\"),\n\
        \              (\"background\", \"#161b22\")\n\
        \            ])\n\
        \          ],\n\
        \          [Text(cellStr(getCell(model.board, pos)))]\n\
        \        )\n\
        \      )\n\
        \    )\n\
        \  in\n\
        \  Div(\n\
        \    [Style([(\"max-width\", \"300px\"), (\"margin\", \"20px auto\"), \
         (\"text-align\", \"center\"),\n\
        \            (\"font-family\", \"monospace\"), (\"background\", \
         \"#0d1117\"), (\"color\", \"#c9d1d9\"),\n\
        \            (\"padding\", \"20px\"), (\"border-radius\", \"12px\"), \
         (\"border\", \"1px solid #30363d\")])],\n\
        \    [\n\
        \      H2([Style([(\"color\", \"#3fb950\"), (\"margin-bottom\", \
         \"4px\")])], [Text(\"\240\159\140\177 Sprouts and Shrooms \
         \240\159\141\132\")]),\n\
        \      P([Style([(\"font-size\", \"16px\"), (\"margin-bottom\", \
         \"15px\"), (\"color\", \"#8b949e\")])], [Text(statusText)]),\n\
        \      Div(\n\
        \        [Style([(\"display\", \"inline-block\")])],\n\
        \        [boardRow([0, 1, 2]), boardRow([3, 4, 5]), boardRow([6, 7, 8])]\n\
        \      ),\n\
        \      Div(\n\
        \        [Style([(\"margin-top\", \"15px\")])],\n\
        \        [\n\
        \          Button(\n\
        \            [\n\
        \              OnClick(NewGame),\n\
        \              Style([(\"padding\", \"10px 20px\"), (\"font-size\", \
         \"14px\"), (\"background\", \"#238636\"),\n\
        \                     (\"color\", \"white\"), (\"border\", \"none\"), \
         (\"cursor\", \"pointer\"),\n\
        \                     (\"border-radius\", \"6px\"), (\"font-family\", \
         \"monospace\")])\n\
        \            ],\n\
        \            [Text(\"New Plot\")]\n\
        \          )\n\
        \        ]\n\
        \      )\n\
        \    ]\n\
        \  )\n\
         in\n\n\
         let subs(_model: Model): Sub = SubNone in\n\n\
         # ===== TESTS ===== #\n\n\
         let play(m: Model, moves: [Int]): Model = fold_left(moves, move, m) \
         in\n\n\
         hint \"initial board is empty\"\n\
         test for_all(init.board, fun c -> c == Empty) end;\n\n\
         hint \"sprout plays first\"\n\
         test init.turn == PlayerSprout end;\n\n\
         hint \"game starts in progress\"\n\
         test init.status == InProgress end;\n\n\
         hint \"move places correct marker\"\n\
         test\n\
        \  let m = move(init, 0) in\n\
        \  getCell(m.board, 0) == Sprout\n\
         end;\n\n\
         hint \"turn alternates after move\"\n\
         test\n\
        \  let m = move(init, 0) in\n\
        \  m.turn == PlayerShroom\n\
         end;\n\n\
         hint \"second move places a shroom\"\n\
         test\n\
        \  let m = play(init, [0, 4]) in\n\
        \  getCell(m.board, 4) == Shroom\n\
         end;\n\n\
         hint \"invalid move on occupied cell\"\n\
         test\n\
        \  let m = play(init, [0, 0]) in  # Sprout plays 0, Shroom tries 0 #\n\
        \  getCell(m.board, 0) == Sprout &&\n\
        \  m.turn == PlayerShroom\n\
         end;\n\n\
         hint \"sprout wins with top row\"\n\
         test\n\
        \  let m = play(init, [0, 3, 1, 4, 2]) in\n\
        \  m.status == Won(PlayerSprout)\n\
         end;\n\n\
         hint \"shroom wins with middle column\"\n\
         test\n\
        \  let m = play(init, [0, 1, 2, 4, 6, 7]) in\n\
        \  m.status == Won(PlayerShroom)\n\
         end;\n\n\
         hint \"shroom wins with bottom row\"\n\
         test\n\
        \  let m = play(init, [0, 6, 1, 7, 4, 8]) in\n\
        \  m.status == Won(PlayerShroom)\n\
         end;\n\n\
         hint \"sprout wins with main diagonal\"\n\
         test\n\
        \  let m = play(init, [0, 1, 4, 2, 8]) in\n\
        \  m.status == Won(PlayerSprout)\n\
         end;\n\n\
         hint \"sprout wins with anti-diagonal\"\n\
         test\n\
        \  let m = play(init, [2, 0, 4, 1, 6]) in\n\
        \  m.status == Won(PlayerSprout)\n\
         end;\n\n\
         hint \"sprout wins with left column\"\n\
         test\n\
        \  let m = play(init, [0, 1, 3, 4, 6]) in\n\
        \  m.status == Won(PlayerSprout)\n\
         end;\n\n\
         hint \"sprout wins with right column\"\n\
         test\n\
        \  let m = play(init, [2, 0, 5, 1, 8]) in\n\
        \  m.status == Won(PlayerSprout)\n\
         end;\n\n\
         hint \"draw when board full with no winner\"\n\
         test\n\
        \  let m = play(init, [0, 1, 2, 5, 3, 6, 4, 8, 7]) in\n\
        \  case m.status | Draw => true | _ => false end\n\
         end;\n\n\
         hint \"no moves after win\"\n\
         test\n\
        \  let m = play(init, [0, 3, 1, 4, 2, 5]) in\n\
        \  case m.status | Won(PlayerSprout) => getCell(m.board, 5) == Empty | \
         _ => false end\n\
         end;\n\n\
         hint \"can't move to position 9 or higher\"\n\
         test\n\
        \  let m = move(init, 9) in\n\
        \  for_all(m.board, fun c -> c == Empty)\n\
         end;\n\n\
         hint \"can't move to negative position\"\n\
         test\n\
        \  let m = move(init, -1) in\n\
        \  for_all(m.board, fun c -> c == Empty)\n\
         end;\n\n\
         hint \"new game resets\"\n\
         test\n\
        \  let m = play(init, [0, 1, 4]) in\n\
        \  let (m2, _cmd) = update(NewGame, m) in\n\
        \  for_all(m2.board, fun c -> c == Empty) && m2.turn == PlayerSprout\n\
         end;\n\n\
         (init, update, view, subs)\n";
      refractors = "()";
    } )
